#include <LVRS/ModelAdapter.h>
#include <future>
#include <iostream>
#include <stdexcept>
using Value=ii::core::Value;
namespace {
void check(bool value,const char* message){if(!value)throw std::runtime_error(message);}
template<class T>T take(ii::core::Result<T> value){if(!value)throw std::runtime_error(value.error().message);return std::move(*value);}
void good(ii::core::Result<void> value){if(!value)throw std::runtime_error(value.error().message);}
struct Rows final:lvrs::ItemModel {
    int rows=2,columns=2;mutable int reads=0;
    int rowCount()const override{return rows;}
    int columnCount()const override{return columns;}
    std::map<int,std::string> roleNames()const override{return {{7,"label"},{8,"index"},{9,"column"},{10,"empty"},{11,"missing"},{12,""}};}
    std::optional<Value> data(int r,int c,int role)const override{
        ++reads;if(role==0)return Value("Display");if(role==2)return Value("Edit");
        if(role==7)return Value("R"+std::to_string(r)+"C"+std::to_string(c));
        if(role==8||role==9)return Value(999);if(role==10)return Value{};return {};
    }
    ii::core::Result<void> announce(lvrs::ItemModelEvent event){return publish(event);}
};
struct Sequence final:lvrs::ModelSequence {
    int size=3;int count()const override{return size;}
    lvrs::ModelEntry at(int index)const override{return index>=0&&index<size?lvrs::ModelEntry(Value(index*10)):lvrs::ModelEntry{};}
};
struct Properties final:lvrs::ModelProperties {
    std::optional<Value> read_property(std::string_view key)const override{if(key=="label")return Value("Live");if(key=="null")return Value{};return {};}
    ii::core::Result<bool> write_property(std::string_view,Value)override{return false;}
    Value::Object model_descriptor()const override{return {};}
};
lvrs::ModelInput input(const std::shared_ptr<Rows>& rows){return std::shared_ptr<const lvrs::ItemModel>(rows);}
void defaults(){lvrs::ModelSource m;check(m.count()==0&&m.column()==0&&m.revision()==0&&!m.itemModel(),"Default state changed");check(!m.at(-1).valid()&&!m.at(0).valid()&&m.row(0).empty(),"Empty source produced an entry");check(!take(m.setSource({}))&&!take(m.setColumn(-1)),"Default no-op changed revision");}
void values(){lvrs::ModelSource m;Value original(Value::Array{Value("One"),Value{},Value(3)});check(take(m.setSource(original))&&m.count()==3&&!m.itemModel(),"Owned array not recognized");check(m.at(1).valid()&&m.at(1).value()==Value{},"Present null collapsed into missing");check(!m.at(3).valid()&&m.at(0).value()==Value("One"),"Array boundary changed");check(!take(m.setSource(original))&&m.revision()==1,"Equal owned source was treated as new");check(take(m.setSource(Value(5)))&&m.count()==0&&!m.at(0).valid(),"Scalar became an implicit model");}
void rows(){auto data=std::make_shared<Rows>();lvrs::ModelSource m;check(take(m.setSource(input(data)))&&m.count()==2&&m.itemModel(),"Item model not recognized");auto row=m.row(1);check(row.at("label")==Value("R1C0")&&row.at("display")==Value("Display")&&row.at("edit")==Value("Edit"),"Roles or display/edit fallback changed");check(row.at("index")==Value(1)&&row.at("row")==Value(1)&&row.at("column")==Value(0),"Metadata did not replace colliding roles");check(row.contains("empty")&&!row.contains("missing")&&!row.contains(""),"Null/absent/empty-name roles changed");check(m.at(1).value()==Value(row)&&m.row(-1).empty()&&m.row(2).empty(),"Item access and row access disagree");}
void columns(){auto data=std::make_shared<Rows>();lvrs::ModelSource m;take(m.setSource(input(data)));take(m.setColumn(1));check(m.row(0).at("label")==Value("R0C1"),"Selected column ignored");take(m.setColumn(20));check(m.column()==20&&m.row(0).at("column")==Value(0),"Out-of-range column did not fall back to zero");take(m.setColumn(-2));check(m.column()==0,"Negative column was not clamped");data->columns=0;check(m.row(0).empty(),"Invalid model index returned roles");}
void adapter(){lvrs::ModelAdapter a;auto data=std::make_shared<Rows>();auto model=input(data);check(a.isItemModel(model)&&a.count(model)==2,"Adapter missed native item model");check(a.row(model,1,99).at("column")==Value(0)&&a.row(model,-1).empty(),"Adapter row bounds differ");lvrs::ModelSource s;take(s.setSource(model));check(s.row(0)==a.row(model,0),"Two row projections diverged");check(!a.isItemModel(Value(Value::Array{}))&&a.count(Value(Value::Array{Value(1)}))==0,"Adapter accepted an ordinary list");data->rows=-4;check(a.count(model)==0,"Negative item count not clamped");}
void sequence(){auto data=std::make_shared<Sequence>();lvrs::ModelSource m;take(m.setSource(std::shared_ptr<const lvrs::ModelSequence>(data)));check(m.count()==3&&!m.itemModel()&&m.at(2).value()==Value(20)&&m.row(0).empty(),"Explicit sequence contract changed");data->size=1;auto revision=m.revision();good(m.invalidate());check(m.count()==1&&m.revision()==revision+1&&!m.at(1).valid(),"Manual sequence invalidation failed");data.reset();check(m.count()==0&&!m.at(0).valid(),"Expired sequence was dereferenced");}
void roles(){lvrs::ModelSource m;lvrs::ModelEntry e(Value(Value::Object{{"label",Value("Hello")},{"null",Value{}}}));check(m.roleValue(e," label ")==Value("Hello")&&m.roleValue(e,"absent",Value("Fallback"))==Value("Fallback"),"Role trimming/fallback changed");check(m.roleValue(e,"null",Value("Fallback"))->kind()==ii::core::ValueKind::null&&!m.roleValue(e,"absent")&&m.roleValue(e,"null").has_value(),"Missing role and present null were conflated");check(m.textValue(e,Value(Value::Array{Value("null"),Value("label")}))=="Hello","Ordered role lookup failed");check(m.textValue(lvrs::ModelEntry(Value(42)),Value("label"))=="42"&&m.textValue({},Value("label"),"Fallback")=="Fallback","Scalar text or missing fallback changed");}
void objects(){auto object=std::make_shared<Properties>();lvrs::ModelEntry entry{std::shared_ptr<const lvrs::ModelProperties>(object)};lvrs::ModelSource m;check(m.textValue(entry,Value("label"))=="Live"&&m.roleValue(entry,"null",Value(1))==Value{},"Native object provider not queried");object.reset();check(!entry.valid()&&m.textValue(entry,Value("label"),"Retired")=="Retired","Retired object entry remained live");}
void conversion(){lvrs::ModelSource m;const auto entry=[](Value v){return lvrs::ModelEntry(Value(Value::Object{{"value",std::move(v)}}));};check(m.boolValue(entry(Value(true)),"value")&&!m.boolValue(entry(Value("true")),"value",true),"Legacy integer-first string boolean conversion changed");check(m.boolValue(entry(Value(" +12 ")),"value")&&!m.boolValue(entry(Value("no")),"value",true),"Numeric string boolean conversion changed");check(m.intValue(entry(Value(" -42 ")),"value",9)==-42&&m.intValue(entry(Value("bad")),"value",9)==9,"Integer text parse/fallback failed");check(m.intValue(entry(Value(1.6)),"value")==2&&m.intValue(entry(Value(-1.5)),"value")==-2,"Qt integer rounding changed");check(m.intValue(entry(Value(UINT64_MAX)),"value",77)==-1&&m.intValue(entry(Value("2147483648")),"value")==INT32_MIN,"Defined 32-bit narrowing changed");check(m.intValue(entry(Value(1e20)),"value",77)==77,"Unrepresentable real did not use safe fallback");}
void events(){lvrs::ModelSource m;std::vector<lvrs::ModelSourceEvent> events;auto port=std::make_shared<lvrs::ModelSourceChangePort>([&](const auto& e){events.push_back(e.event);check(e.revision==m.revision(),"Observer saw uncommitted revision");});good(m.observe(port));take(m.setSource(Value(Value::Array{Value(1)})));check(events==std::vector{lvrs::ModelSourceEvent::source,lvrs::ModelSourceEvent::revision,lvrs::ModelSourceEvent::count},"Source notification order differs");events.clear();take(m.setColumn(1));check(events==std::vector{lvrs::ModelSourceEvent::column,lvrs::ModelSourceEvent::revision},"Column changed count");events.clear();good(m.invalidate());check(events==std::vector{lvrs::ModelSourceEvent::revision,lvrs::ModelSourceEvent::count},"Explicit invalidate did not always notify count");}
void observation(){auto data=std::make_shared<Rows>(),other=std::make_shared<Rows>();lvrs::ModelSource m;take(m.setSource(input(data)));for(auto event:{lvrs::ItemModelEvent::rows_inserted,lvrs::ItemModelEvent::rows_removed,lvrs::ItemModelEvent::rows_moved,lvrs::ItemModelEvent::reset,lvrs::ItemModelEvent::layout,lvrs::ItemModelEvent::data}){const auto before=m.revision();good(data->announce(event));check(m.revision()==before+1,"Item model event did not invalidate");}take(m.setSource(input(other)));const auto before=m.revision();good(data->announce(lvrs::ItemModelEvent::data));check(m.revision()==before,"Old source subscription leaked");const std::weak_ptr<const lvrs::ItemModel> weak=other;const lvrs::ItemModel* raw=other.get();int retired=0;
    auto terminal=std::make_shared<lvrs::ItemModelChangePort>([&](const auto& event){if(event==lvrs::ItemModelEvent::retired){++retired;check(weak.expired(),"Retirement revived the provider");auto rejected=raw->observe({});check(!rejected&&rejected.error().code==ii::core::ErrorCode::closed,"Retirement admitted another observer");}});
    good(other->observe(terminal));other.reset();check(retired==1&&m.count()==0&&!m.itemModel()&&m.revision()==before+1,"Model retirement did not invalidate safely");}
void errors(){lvrs::ModelSource m;auto port=std::make_shared<lvrs::ModelSourceChangePort>([&](const auto&){auto reentrant=m.setColumn(3);check(!reentrant&&reentrant.error().code==ii::core::ErrorCode::busy,"Reentrant mutation admitted");throw std::runtime_error("observer");});good(m.observe(port));auto changed=m.setSource(Value(Value::Array{Value(1)}));check(!changed&&m.count()==1&&m.revision()==1&&m.column()==0,"Observer error rolled back committed state");port.reset();good(m.invalidate());check(m.revision()==2,"Failed observer left model busy");auto wrong=std::async(std::launch::async,[&]{return m.setColumn(1);}).get();check(!wrong&&wrong.error().code==ii::core::ErrorCode::wrong_executor,"Foreign-thread write admitted");}
void pending(){auto data=std::make_shared<Rows>();lvrs::ModelSource m;take(m.setSource(input(data)));bool once=false;auto port=std::make_shared<lvrs::ModelSourceChangePort>([&](const auto& e){if(!once&&e.event==lvrs::ModelSourceEvent::revision){once=true;good(data->announce(lvrs::ItemModelEvent::data));}});good(m.observe(port));good(m.invalidate());check(m.revision()==3,"An upstream change during notification was lost");}
void malformed_numbers(){lvrs::ModelSource m;for(const auto* text:{"+-42","++42","--42","-+42","+ 42","42.0","0x10","9223372036854775808"}){lvrs::ModelEntry entry(Value(Value::Object{{"number",Value(text)}}));check(m.intValue(entry,"number",77)==77&&!m.boolValue(entry,"number",true),"Malformed or overflowing integer text was accepted");}}
void retirement(){auto data=std::make_shared<Rows>();{lvrs::ModelSource m;take(m.setSource(input(data)));}good(data->announce(lvrs::ItemModelEvent::data));check(data.use_count()==1,"Source retained provider ownership");}
void nonmutation(){auto data=std::make_shared<Rows>();lvrs::ModelSource m;take(m.setSource(input(data)));const auto before=m.revision();for(int i=0;i<100;++i){(void)m.count();(void)m.at(i%2);(void)m.row(i%2);}check(m.revision()==before&&data->rows==2&&data->columns==2,"Read projection mutated source or local revision");}
}
int main(int argc,char** argv){try{const std::string name=argc>1?argv[1]:"defaults";
    if(name=="conversion")malformed_numbers();
    if(name=="defaults")defaults();else if(name=="values")values();else if(name=="rows")rows();else if(name=="columns")columns();else if(name=="adapter")adapter();else if(name=="sequence")sequence();else if(name=="roles")roles();else if(name=="objects")objects();else if(name=="conversion")conversion();else if(name=="events")events();else if(name=="observation")observation();else if(name=="errors")errors();else if(name=="pending")pending();else if(name=="retirement")retirement();else if(name=="nonmutation")nonmutation();else throw std::runtime_error("Unknown model-source test");
    std::cout<<"Native model source "<<name<<" passed\n";
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
